from __future__ import annotations
import json,sys
from pathlib import Path
from builder_lib import Graph,atom,any_,all_,not_,opt,fact,upsert_fact,set_roles,src_prov
ROOT=Path(__file__).resolve().parents[1]; ENC=ROOT/'backend/nexus/guidelines/encoded'
def load(n): return json.loads((ENC/n).read_text())
def save(n,p): (ENC/n).write_text(json.dumps(p,indent=2))
def prov(p,s): return src_prov(p,s)
def finalize(p,g,roles,derived=None,consistency=None):
    p['nodes']=g.nodes; set_roles(p,roles); p['derived_rules']=derived or []; p['consistency_rules']=consistency or []
    p['lifecycle']={**p.get('lifecycle',{}),'package_status':'DRAFT','clinical_status':'REQUIRES_CLINICAL_REVIEW','runtime_eligible':False}
    return p

def addfacts(p, specs):
    for x in specs: upsert_fact(p,x)

def roles_for(p, routing=(), option=(), derived=(), context=()):
    r={d['key']:'NON_ROUTING_CONTEXT' for d in p['fact_definitions']}
    for k in routing:r[k]='ROUTING'
    for k in option:r[k]='OPTION_APPLICABILITY'
    for k in derived:r[k]='DERIVED_DETERMINISTIC'
    for k in context:r[k]='NON_ROUTING_CONTEXT'
    return r

def anal_builder():
    n='nexus_anal_carcinoma_v2_2026.json'; p=load(n)
    addfacts(p,[
      fact('perianal_early_local_excision_eligible','BOOLEAN'),fact('excision_margin_adequate','BOOLEAN'),
      fact('recurrence_site','CODED',['LOCAL','INGUINAL','METASTATIC','UNKNOWN'],semantic_unknown=['UNKNOWN']),
      fact('prior_rt','BOOLEAN'),fact('definitive_rt_possible','BOOLEAN'),
      fact('metastatic_line','CODED',['FIRST','SECOND_OR_LATER','UNKNOWN'],semantic_unknown=['UNKNOWN']),
      fact('prior_immunotherapy','BOOLEAN'),fact('suspicious_inguinal_nodes','BOOLEAN',role='OPTION_APPLICABILITY')])
    r=roles_for(p,routing=['cancer_type','histology','primary_site','clinical_m','treatment_phase','post_chemoradiation_status','resectable_local_recurrence','perianal_early_local_excision_eligible','excision_margin_adequate','recurrence_site','prior_rt','definitive_rt_possible','metastatic_line'],option=['prior_immunotherapy','suspicious_inguinal_nodes'])
    g=Graph(); S=lambda *x:list(x)
    g.decision('scope','Anal carcinoma?',atom('cancer_type','eq','ANAL_CARCINOMA'),'hist','outside',S('ANAL-1'))
    g.decision('hist','Squamous cell carcinoma?',atom('histology','eq','SQUAMOUS_CELL'),'care_met','other_hist',S('ANAL-1'))
    g.status('other_hist','Non-squamous anal histology requires the histology-specific NCCN guideline.','NEEDS_DIFFERENT_PATHWAY',S('ANAL-1'))
    g.decision('care_met','Current metastatic episode?',any_(atom('treatment_phase','eq','METASTATIC'),atom('clinical_m','eq','M1')),'met_line','care_recur',S('ANAL-1','ANAL-2','ANAL-B'))
    g.decision('care_recur','Current recurrence episode?',atom('treatment_phase','eq','RECURRENT'),'rec_site','care_post',S('ANAL-3','ANAL-4'))
    g.decision('care_post','Post-chemoradiation response assessment?',atom('treatment_phase','eq','POST_CHEMORADIATION'),'post_resp','site',S('ANAL-3'))
    g.decision('site','Anal canal primary?',atom('primary_site','eq','ANAL_CANAL'),'canal_m','perianal_confirm',S('ANAL-1','ANAL-2'))
    g.decision('perianal_confirm','Perianal primary?',atom('primary_site','eq','PERIANAL'),'perianal_m','need_site',S('ANAL-2'))
    g.status('need_site','Anal canal versus perianal primary site is required.','NEEDS_INFORMATION',S('ANAL-1','ANAL-2'))
    g.decision('canal_m','Metastatic disease?',atom('clinical_m','eq','M1'),'met_line','canal_local',S('ANAL-1'))
    g.action('canal_local','Locoregional anal canal squamous cell carcinoma: definitive chemoradiation.',S('ANAL-1'),[
      opt('anal_5fu_mmc_rt','Fluorouracil + mitomycin + RT',src=prov(p,'ANAL-1')),
      opt('anal_cape_mmc_rt','Capecitabine + mitomycin + RT',src=prov(p,'ANAL-1')),
      opt('anal_cis_5fu_rt','Cisplatin + fluorouracil + RT','Category 2B.',evidence='CATEGORY_2B',src=prov(p,'ANAL-1'))],support=['ANAL-B','ANAL-C'],pathway_id='ANAL_CANAL_LOCOREGIONAL')
    g.decision('perianal_m','Metastatic disease?',atom('clinical_m','eq','M1'),'met_line','perianal_early',S('ANAL-2'))
    g.decision('perianal_early','T1N0 well/moderately differentiated or select T2N0 appropriate for local excision?',atom('perianal_early_local_excision_eligible','eq',True),'perianal_excision','perianal_definitive',S('ANAL-2'))
    g.decision('perianal_excision','Adequate excision margins?',atom('excision_margin_adequate','eq',True),'perianal_observe','perianal_inadequate',S('ANAL-2'))
    g.action('perianal_observe','Early perianal cancer after local excision with adequate margins: surveillance.',S('ANAL-2','ANAL-3'),[opt('anal_surveillance','Surveillance per ANAL-3')],support=['ANAL-D'],pathway_id='ANAL_PERIANAL_EXCISED')
    g.action('perianal_inadequate','Early perianal cancer with inadequate local-excision margins: re-excision preferred when feasible or local RT +/- chemotherapy.',S('ANAL-2'),[
      opt('anal_reexcision','Re-excision','Preferred when feasible.',preference='PREFERRED'),
      opt('anal_local_rt','Local RT +/- fluoropyrimidine/mitomycin','If re-excision not feasible/appropriate.')],support=['ANAL-B','ANAL-C'],pathway_id='ANAL_PERIANAL_INADEQUATE_MARGIN')
    g.action('perianal_definitive','Perianal squamous cell carcinoma not meeting local-excision criteria: definitive chemoradiation.',S('ANAL-2'),[
      opt('anal_peri_5fu_mmc_rt','Fluorouracil + mitomycin + RT'),opt('anal_peri_cape_mmc_rt','Capecitabine + mitomycin + RT'),opt('anal_peri_cis_5fu_rt','Cisplatin + fluorouracil + RT','Category 2B.',evidence='CATEGORY_2B')],support=['ANAL-B','ANAL-C'],pathway_id='ANAL_PERIANAL_LOCOREGIONAL')
    g.decision('post_resp','Complete remission?',atom('post_chemoradiation_status','eq','COMPLETE_RESPONSE'),'surv','post_persistent',S('ANAL-3'))
    g.decision('post_persistent','Persistent disease without progression?',atom('post_chemoradiation_status','eq','PERSISTENT'),'persistent_obs','post_progressive',S('ANAL-3','ANAL-4'))
    g.action('persistent_obs','Persistent anal carcinoma without progression after chemoradiation: serial clinical reassessment can continue up to the source-defined observation window; biopsy/restage if progression suspected.',S('ANAL-4'),[opt('anal_persist_reassess','Serial reassessment up to 6 months if no progression')],pathway_id='ANAL_PERSISTENT')
    g.decision('post_progressive','Progressive disease?',atom('post_chemoradiation_status','eq','PROGRESSIVE'),'progressive_salvage','need_postresp',S('ANAL-4'))
    g.status('need_postresp','Post-chemoradiation response status is required.','NEEDS_INFORMATION',S('ANAL-3','ANAL-4'))
    g.action('progressive_salvage','Biopsy-confirmed progressive local disease after definitive chemoradiation: salvage APR +/- groin dissection as indicated; metastatic disease routes to systemic therapy.',S('ANAL-4'),[opt('anal_apr','Abdominoperineal resection (APR)'),opt('anal_groin_dissection','Groin dissection if involved nodes',app=atom('suspicious_inguinal_nodes','eq',True))],support=['ANAL-A'],pathway_id='ANAL_PROGRESSIVE_SALVAGE')
    g.action('surv','Complete response after treatment: ANAL-3 surveillance.',S('ANAL-3'),[opt('anal_followup','DRE, anoscopy and inguinal node surveillance at source-defined intervals')],support=['ANAL-D'],pathway_id='ANAL_SURVEILLANCE')
    g.decision('rec_site','Recurrence site?',atom('recurrence_site','eq','LOCAL'),'rec_local','rec_inguinal_check',S('ANAL-3'))
    g.decision('rec_inguinal_check','Inguinal recurrence?',atom('recurrence_site','eq','INGUINAL'),'rec_inguinal','rec_met_check',S('ANAL-3'))
    g.decision('rec_met_check','Metastatic recurrence?',atom('recurrence_site','eq','METASTATIC'),'met_line','need_recsite',S('ANAL-3'))
    g.status('need_recsite','Recurrence site is required to select salvage pathway.','NEEDS_INFORMATION',S('ANAL-3'))
    g.decision('rec_local','Local recurrence resectable for salvage APR?',atom('resectable_local_recurrence','eq',True),'local_apr','local_nonresect',S('ANAL-3','ANAL-4'))
    g.action('local_apr','Local recurrence after prior chemoradiation: salvage APR.',S('ANAL-3'),[opt('anal_rec_apr','Abdominoperineal resection (APR)')],support=['ANAL-A'],pathway_id='ANAL_LOCAL_RECURRENCE_RESECTABLE')
    g.action('local_nonresect','Local recurrence not resectable: individualized systemic/local therapy based on prior RT and feasibility.',S('ANAL-3','ANAL-4'),[opt('anal_rec_reirradiation','Individualized RT/chemoradiation','If technically feasible.',app=atom('definitive_rt_possible','eq',True)),opt('anal_rec_systemic','Systemic therapy')],support=['ANAL-B','ANAL-C'],pathway_id='ANAL_LOCAL_RECURRENCE_NONRESECTABLE')
    g.action('rec_inguinal','Inguinal nodal recurrence: definitive RT preferred when possible; systemic therapy or groin dissection are alternatives based on prior RT.',S('ANAL-3'),[
      opt('anal_ing_rt','Definitive RT','Preferred when possible.',preference='PREFERRED',app=atom('definitive_rt_possible','eq',True)),
      opt('anal_ing_retifanlimab','Carboplatin/paclitaxel + retifanlimab-dlwr'),
      opt('anal_ing_dissection','Groin dissection','Particularly after prior groin RT.',app=atom('prior_rt','eq',True))],support=['ANAL-A','ANAL-B','ANAL-C'],pathway_id='ANAL_INGUINAL_RECURRENCE')
    g.decision('met_line','First-line metastatic therapy?',atom('metastatic_line','eq','FIRST'),'met_first','met_later',S('ANAL-B'))
    g.action('met_first','Metastatic anal carcinoma first-line systemic therapy.',S('ANAL-1','ANAL-2'),[
      opt('anal_met_retifanlimab','Carboplatin + paclitaxel + retifanlimab-dlwr','Preferred.',preference='PREFERRED'),
      opt('anal_met_capeox','CAPEOX'),opt('anal_met_carbotax','Carboplatin + paclitaxel'),opt('anal_met_folfox','Modified FOLFOX6'),opt('anal_met_folc','Cisplatin + fluorouracil','Category 2B.',evidence='CATEGORY_2B'),opt('anal_met_mdcf','Modified DCF','Category 2B.',evidence='CATEGORY_2B')],support=['ANAL-B'],pathway_id='ANAL_METASTATIC_FIRST_LINE')
    g.action('met_later','Metastatic anal carcinoma second-line/subsequent therapy: checkpoint inhibitors when no prior immunotherapy plus unused cytotoxic options.',S('ANAL-3'),[
      opt('anal_later_cpi','Checkpoint inhibitor (cemiplimab, dostarlimab, nivolumab, pembrolizumab, penpulimab, retifanlimab, tislelizumab, or toripalimab)','Preferred if no prior immunotherapy.',preference='PREFERRED',app=atom('prior_immunotherapy','eq',False)),
      opt('anal_later_chemo','Previously unused active chemotherapy regimen')],support=['ANAL-B'],pathway_id='ANAL_METASTATIC_LATER_LINE')
    g.status('outside','Outside anal carcinoma package.','OUTSIDE_ENCODED_SCOPE',S('ANAL-1'))
    cons=[{'id':'anal_m1_nonmet_conflict','when':all_(atom('clinical_m','eq','M1'),atom('treatment_phase','in',['POST_CHEMORADIATION'])),'message':'M1 current disease conflicts with locoregional post-chemoradiation state.','source_pathways':['ANAL-1','ANAL-3']}]
    finalize(p,g,r,consistency=cons); save(n,p)

def bcc_builder():
    n='nexus_basal_cell_skin_cancer_v1_2027.json'; p=load(n)
    addfacts(p,[
      fact('location_high_risk','BOOLEAN'),fact('diameter_high_risk','BOOLEAN'),fact('poorly_defined_borders','BOOLEAN'),fact('recurrent_primary','BOOLEAN'),fact('immunosuppressed','BOOLEAN'),fact('site_prior_rt','BOOLEAN'),fact('aggressive_histology','BOOLEAN'),fact('perineural_involvement','BOOLEAN'),
      fact('margin_status','CODED',['NEGATIVE','POSITIVE','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('named_nerve_involvement','BOOLEAN'),fact('surgery_feasible','BOOLEAN'),fact('local_recurrence','BOOLEAN'),fact('hhi_intolerant_or_progressed','BOOLEAN'),fact('prior_hhi','BOOLEAN')])
    routing=['cancer_type','treatment_phase','disease_extent','resectable','candidate_for_curative_rt','margin_status','named_nerve_involvement','surgery_feasible','local_recurrence']
    derived=['high_risk_any']; opts=['prior_hhi','hhi_intolerant_or_progressed']
    riskfacts=['location_high_risk','diameter_high_risk','poorly_defined_borders','recurrent_primary','immunosuppressed','site_prior_rt','aggressive_histology','perineural_involvement']
    r=roles_for(p,routing=routing+riskfacts,option=opts,derived=derived)
    # derived high risk true when any confirmed risk factor; false cannot be derived from partial unknown -> route directly using all risk checks instead
    g=Graph(); S=lambda *x:list(x)
    g.decision('scope','Basal cell skin cancer?',atom('cancer_type','eq','BASAL_CELL_SKIN_CANCER'),'care_advanced','outside',S('BCC-1'))
    g.decision('care_advanced','Nodal or metastatic/locally advanced current disease?',atom('disease_extent','in',['LOCALLY_ADVANCED','NODAL','METASTATIC']),'extent_la','care_recur',S('BCC-1','BCC-5'))
    g.decision('care_recur','Current recurrence?',atom('treatment_phase','eq','RECURRENCE'),'recur_extent','risk_any',S('BCC-6'))
    g.decision('risk_any','Any confirmed high-risk recurrence factor?',any_(*[atom(x,'eq',True) for x in riskfacts]),'high_local','risk_all_negative',S('BCC-2'))
    g.decision('risk_all_negative','All source-defined high-risk factors confirmed absent?',all_(*[atom(x,'eq',False) for x in riskfacts]),'low_local','need_risk',S('BCC-2'))
    g.status('need_risk','One or more BCC high-risk factors remain unresolved; LOW risk cannot be assigned until all are confirmed absent.','NEEDS_INFORMATION',S('BCC-2'))
    g.decision('low_local','Low-risk BCC postoperative margin positive?',atom('margin_status','eq','POSITIVE'),'low_posmargin','low_primary',S('BCC-3'))
    g.action('low_primary','Low-risk BCC primary treatment.',S('BCC-3'),[
      opt('bcc_low_excision','Standard excision with 4-mm clinical margins'),opt('bcc_low_mohs','Mohs/PDEMA'),opt('bcc_low_ce','Curettage and electrodesiccation','For appropriate low-risk sites/tumors.'),opt('bcc_low_superficial','Superficial-BCC nonsurgical modalities','For clinically/histologically superficial BCC without dermal extension.')],support=['BCC-B','BCC-C'],pathway_id='BCC_LOW_RISK')
    g.action('low_posmargin','Low-risk BCC with positive margins: Mohs/PDEMA, re-excision, or RT for nonsurgical candidates.',S('BCC-3'),[opt('bcc_low_pm_mohs','Mohs/PDEMA'),opt('bcc_low_pm_reexcision','Re-excision if feasible'),opt('bcc_low_pm_rt','RT','For nonsurgical candidates.',app=atom('candidate_for_curative_rt','eq',True))],support=['BCC-B','BCC-C'],pathway_id='BCC_LOW_RISK_POSITIVE_MARGIN')
    g.decision('high_local','Named nerve/perineural extensive involvement?',atom('named_nerve_involvement','eq',True),'high_pn','high_surgery',S('BCC-4'))
    g.decision('high_surgery','Surgery feasible?',atom('surgery_feasible','eq',True),'high_surgery_margin','high_rt',S('BCC-4'))
    g.decision('high_surgery_margin','Postoperative margin positive?',atom('margin_status','eq','POSITIVE'),'high_pm','high_neg',S('BCC-4'))
    g.action('high_neg','High-risk BCC after complete surgery: follow-up; consider adjuvant RT for source-defined extensive nerve/other high-risk indications.',S('BCC-4'),[opt('bcc_high_follow','Follow-up per BCC-6'),opt('bcc_high_adjuvant_rt','Consider adjuvant RT','For source-defined high-risk indications.',decision_relevant=False)],support=['BCC-C'],pathway_id='BCC_HIGH_RISK_RESECTED')
    g.action('high_pm','High-risk BCC with positive margins: re-resection/Mohs-PDEMA preferred when feasible or RT.',S('BCC-4'),[opt('bcc_high_pm_resect','Re-resection/Mohs-PDEMA'),opt('bcc_high_pm_rt','RT',app=atom('candidate_for_curative_rt','eq',True))],support=['BCC-C'],pathway_id='BCC_HIGH_RISK_POSITIVE_MARGIN')
    g.action('high_pn','High-risk BCC with named-nerve/perineural tumor spread: multidisciplinary surgery and/or RT pathway.',S('BCC-4'),[opt('bcc_pn_surgery','Surgery with complete margin assessment',app=atom('surgery_feasible','eq',True)),opt('bcc_pn_rt','RT',app=atom('candidate_for_curative_rt','eq',True))],support=['BCC-C'],pathway_id='BCC_HIGH_RISK_PERINEURAL')
    g.action('high_rt','High-risk BCC not suitable for surgery: definitive RT if candidate; if neither curative surgery nor RT feasible, treat as locally advanced.',S('BCC-4'),[opt('bcc_high_def_rt','Definitive RT',app=atom('candidate_for_curative_rt','eq',True)),opt('bcc_high_to_advanced','Systemic therapy pathway for locally advanced disease',app=atom('candidate_for_curative_rt','eq',False))],support=['BCC-C','BCC-D'],pathway_id='BCC_HIGH_RISK_NONSURGICAL')
    g.decision('extent_la','Locally advanced disease?',atom('disease_extent','eq','LOCALLY_ADVANCED'),'la_resect','extent_nodal',S('BCC-5'))
    g.decision('la_resect','Locally advanced disease resectable with acceptable morbidity?',atom('resectable','eq',True),'la_resect_action','la_hhi_state',S('BCC-5'))
    g.action('la_resect_action','Locally advanced BCC that is resectable: multidisciplinary surgery +/- RT; neoadjuvant vismodegib is useful in selected circumstances.',S('BCC-5'),[opt('bcc_la_surgery','Surgery +/- RT'),opt('bcc_la_neo_vismo','Neoadjuvant vismodegib','Category 2B useful in certain circumstances.',preference='USEFUL_IN_CERTAIN_CIRCUMSTANCES',evidence='CATEGORY_2B')],support=['BCC-B','BCC-C','BCC-D'],pathway_id='BCC_LA_RESECTABLE')
    g.decision('la_hhi_state','Prior HHI with progression/intolerance?',atom('hhi_intolerant_or_progressed','eq',True),'la_second','la_first',S('BCC-D'))
    g.action('la_first','Locally advanced unresectable BCC: HHI preferred first-line systemic therapy.',S('BCC-5'),[opt('bcc_la_vismo','Vismodegib','Preferred.',preference='PREFERRED'),opt('bcc_la_soni','Sonidegib','Preferred.',preference='PREFERRED')],support=['BCC-D'],pathway_id='BCC_LA_UNRESECTABLE_FIRST')
    g.action('la_second','Locally advanced unresectable BCC after HHI progression/intolerance: cemiplimab-rwlc preferred.',S('BCC-5'),[opt('bcc_la_cemip','Cemiplimab-rwlc','Preferred second-line/HHI intolerance.',preference='PREFERRED')],support=['BCC-D'],pathway_id='BCC_LA_AFTER_HHI')
    g.decision('extent_nodal','Nodal disease?',atom('disease_extent','eq','NODAL'),'nodal','extent_met',S('BCC-5'))
    g.action('nodal','Nodal BCC: multidisciplinary surgery/RT when feasible plus state-appropriate systemic therapy; HHI or cemiplimab according to prior HHI exposure.',S('BCC-5'),[
      opt('bcc_nodal_surg','Lymph-node surgery +/- RT',app=atom('resectable','eq',True)),opt('bcc_nodal_vismo','Vismodegib','Preferred if no prior HHI progression.',preference='PREFERRED',app=atom('hhi_intolerant_or_progressed','eq',False)),opt('bcc_nodal_soni','Sonidegib','Category 2B preferred.',preference='PREFERRED',evidence='CATEGORY_2B',app=atom('hhi_intolerant_or_progressed','eq',False)),opt('bcc_nodal_cemi','Cemiplimab-rwlc','Preferred after HHI progression/intolerance.',preference='PREFERRED',app=atom('hhi_intolerant_or_progressed','eq',True))],support=['BCC-C','BCC-D'],pathway_id='BCC_NODAL')
    g.decision('extent_met','Metastatic disease?',atom('disease_extent','eq','METASTATIC'),'met','need_extent',S('BCC-5'))
    g.action('met','Metastatic BCC: cemiplimab-rwlc preferred; HHI options depend on exposure/tolerance.',S('BCC-5'),[
      opt('bcc_met_cemi','Cemiplimab-rwlc','Preferred.',preference='PREFERRED'),opt('bcc_met_vismo','Vismodegib','Systemic option if HHI-naive/not progressed.',app=atom('hhi_intolerant_or_progressed','eq',False)),opt('bcc_met_soni','Sonidegib','Category 2B useful in certain circumstances.',preference='USEFUL_IN_CERTAIN_CIRCUMSTANCES',evidence='CATEGORY_2B',app=atom('hhi_intolerant_or_progressed','eq',False))],support=['BCC-D'],pathway_id='BCC_METASTATIC')
    g.status('need_extent','Advanced BCC disease extent is unresolved.','NEEDS_INFORMATION',S('BCC-5'))
    g.decision('recur_extent','Advanced recurrence (locally advanced/nodal/metastatic)?',atom('disease_extent','in',['LOCALLY_ADVANCED','NODAL','METASTATIC']),'extent_la','recur_local',S('BCC-6'))
    g.action('recur_local','Local BCC recurrence: re-stage risk as high-risk and select surgery/RT by feasibility.',S('BCC-6'),[opt('bcc_rec_mohs','Mohs/PDEMA or re-excision',app=atom('surgery_feasible','eq',True)),opt('bcc_rec_rt','RT',app=atom('candidate_for_curative_rt','eq',True))],support=['BCC-B','BCC-C'],pathway_id='BCC_LOCAL_RECURRENCE')
    g.status('outside','Outside BCC package.','OUTSIDE_ENCODED_SCOPE',S('BCC-1'))
    finalize(p,g,r); save(n,p)

def gist_builder():
    n='nexus_gastrointestinal_stromal_tumors_v1_2026.json'; p=load(n)
    addfacts(p,[fact('primary_site','CODED',['STOMACH','SMALL_BOWEL','COLORECTAL','ESOPHAGEAL_EGJ','DUODENUM','OTHER','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('tumor_size_cm','NUMERIC'),fact('mitotic_rate_per_5mm2','NUMERIC'),fact('prior_tki','CODED',['NONE','IMATINIB','SUNITINIB','REGORAFENIB','RIPRETINIB','AVAPRITINIB','OTHER','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('treatment_line','CODED',['FIRST','SECOND','THIRD','FOURTH_PLUS','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('local_progression_amenable','BOOLEAN'),fact('postop_resection_complete','BOOLEAN')])
    r=roles_for(p,routing=['cancer_type','treatment_phase','very_small_gastric_lt2cm','high_risk_eus_or_biopsy','resectable','significant_surgical_morbidity','genotype','postop_resection_complete','recurrence_risk','response_status','progression_extent','primary_site','treatment_line','local_progression_amenable'],option=['tumor_size_cm','mitotic_rate_per_5mm2','prior_tki'])
    g=Graph(); S=lambda *x:list(x)
    g.decision('scope','GIST?',atom('cancer_type','eq','GIST'),'care_prog','outside',S('GIST-1'))
    g.decision('care_prog','Progressive disease?',any_(atom('treatment_phase','eq','PROGRESSIVE'),atom('response_status','eq','PROGRESSION')),'prog_extent','care_unres',S('GIST-5'))
    g.decision('care_unres','Unresectable/metastatic/recurrent episode?',atom('treatment_phase','eq','UNRESECTABLE_METASTATIC'),'unres_line','care_post',S('GIST-4'))
    g.decision('care_post','Postoperative episode?',atom('treatment_phase','eq','POSTOPERATIVE'),'post_complete','initial_small',S('GIST-3'))
    g.decision('initial_small','Very small gastric GIST <2 cm?',atom('very_small_gastric_lt2cm','eq',True),'small_risk','initial_resect',S('GIST-1'))
    g.decision('small_risk','High-risk EUS/biopsy features?',atom('high_risk_eus_or_biopsy','eq',True),'small_resect','small_observe',S('GIST-1'))
    g.action('small_resect','Very small gastric GIST with high-risk features: complete surgical resection.',S('GIST-1'),[opt('gist_small_resection','Complete surgical resection')],support=['GIST-A','GIST-C'],pathway_id='GIST_SMALL_HIGH_RISK')
    g.action('small_observe','Very small gastric GIST without high-risk features: periodic endoscopic or radiographic surveillance can be considered.',S('GIST-1'),[opt('gist_small_surveillance','Periodic endoscopic/radiographic surveillance')],support=['GIST-F'],pathway_id='GIST_SMALL_LOW_RISK')
    g.decision('initial_resect','Resectable?',atom('resectable','eq',True),'initial_morbidity','unres_line',S('GIST-1'))
    g.decision('initial_morbidity','Would resection have significant morbidity / is neoadjuvant cytoreduction indicated?',atom('significant_surgical_morbidity','eq',True),'neo_genotype','direct_resection',S('GIST-1','GIST-2'))
