    g.decision('site_e','Extrahepatic cholangiocarcinoma?',atom('primary_site','eq','EXTRAHEPATIC_CHOLANGIOCARCINOMA'),'e_care','need_site',S('EXTRA-1'))
    g.status('need_site','Biliary primary site must be classified as gallbladder, intrahepatic CCA, or extrahepatic CCA.','NEEDS_INFORMATION',S('GALL-1','INTRA-1','EXTRA-1'))
    # Gallbladder presentation and postop
    g.decision('gb_care','Current unresectable/recurrent/metastatic episode?',any_(atom('treatment_phase','eq','RECURRENT_UNRESECTABLE_METASTATIC'),atom('metastatic','eq',True)),'sys_line','gb_post',S('GALL-5','BIL-C'))
    g.decision('gb_post','Post-cholecystectomy/incidental pathology episode?',atom('treatment_phase','in',['INCIDENTAL_POST_CHOLECYSTECTOMY','POST_RESECTION']),'gb_post_t','gb_presentation',S('GALL-3','GALL-6'))
    g.decision('gb_presentation','Incidental intraoperative suspicious mass?',atom('presentation','eq','INCIDENTAL_INTRAOP'),'gb_intraop_resect','gb_mass',S('GALL-1','GALL-2'))
    g.decision('gb_intraop_resect','Hepatobiliary surgery expertise/resectability permits definitive resection?',atom('resectable','eq',True),'gb_intraop_surg','gb_defer',S('GALL-1','GALL-2'))
    g.action('gb_intraop_surg','Suspicious gallbladder mass found during surgery with hepatobiliary expertise: definitive oncologic resection/staging if appropriate.',S('GALL-1'),[opt('gb_onc_resection','Oncologic resection with appropriate liver/lymph-node surgery')],support=['GALL-A','GALL-B'],pathway_id='GALLBLADDER_INTRAOP_RESECTABLE')
    g.action('gb_defer','Suspicious gallbladder mass when definitive hepatobiliary expertise/resection unavailable: avoid non-oncologic definitive manipulation; obtain appropriate staging/referral.',S('GALL-2'),[opt('gb_referral','Refer to hepatobiliary multidisciplinary team')],support=['GALL-A'],pathway_id='GALLBLADDER_INTRAOP_REFERRAL')
    g.decision('gb_mass','Mass on imaging or jaundice presentation?',atom('presentation','in',['MASS_ON_IMAGING','JAUNDICE','OTHER']),'gb_primary_resect','need_present',S('GALL-4','GALL-5'))
    g.status('need_present','Gallbladder presentation type is required.','NEEDS_INFORMATION',S('GALL-1','GALL-3','GALL-4','GALL-5'))
    g.decision('gb_primary_resect','Resectable nonmetastatic gallbladder cancer?',all_(atom('resectable','eq',True),atom('metastatic','eq',False)),'gb_primary_action','sys_line',S('GALL-4','GALL-5'))
    g.action('gb_primary_action','Resectable gallbladder cancer: oncologic resection; selected patients may receive individualized neoadjuvant systemic therapy/clinical trial.',S('GALL-4'),[opt('gb_primary_surgery','Oncologic resection'),opt('gb_neoadj','Consider neoadjuvant systemic therapy/clinical trial','Individualized with MDT.',decision_relevant=False)],support=['GALL-A','BIL-C'],pathway_id='GALLBLADDER_RESECTABLE')
