def cervical_builder():
    n='nexus_cervical_cancer_v2_2026.json'; p=load(n)
    addfacts(p,[
      fact('cone_margin_status','CODED',['NEGATIVE','POSITIVE_DYSPLASIA','POSITIVE_CARCINOMA','UNKNOWN'],semantic_unknown=['UNKNOWN']),
      fact('tumor_size_cm','NUMERIC'),fact('depth_invasion_mm','NUMERIC'),fact('pelvic_nodes_positive','BOOLEAN'),fact('para_aortic_nodes_positive','BOOLEAN'),
      fact('central_recurrence','BOOLEAN'),fact('recurrence_outside_prior_rt_field','BOOLEAN'),fact('local_treatment_amenable','BOOLEAN'),
      fact('systemic_line','CODED',['FIRST','SECOND_OR_LATER','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('tmb_high','BOOLEAN'),fact('her2_positive','BOOLEAN'),fact('her2_mutant','BOOLEAN'),fact('ntrk_fusion','BOOLEAN'),fact('ret_fusion','BOOLEAN'),fact('prior_checkpoint_inhibitor','BOOLEAN'),fact('cisplatin_intolerant','BOOLEAN'),
      fact('necc_disease_extent','CODED',['CERVIX_CONFINED','LOCALLY_ADVANCED','DISTANT_METASTATIC','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('necc_response','CODED',['RESPONSE','PERSISTENT_RECURRENT','UNKNOWN'],semantic_unknown=['UNKNOWN'])])
    routing=['cancer_type','histology','treatment_phase','figo_stage','lvsi','fertility_sparing_desired','conservative_surgery_criteria_met','medically_operable','positive_nodes','positive_margin','positive_parametrium','distant_metastases','prior_pelvic_rt','recurrence_resectable_or_local_treatable','cone_margin_status','tumor_size_cm','depth_invasion_mm','pelvic_nodes_positive','para_aortic_nodes_positive','central_recurrence','recurrence_outside_prior_rt_field','local_treatment_amenable','systemic_line','necc_disease_extent','necc_response']
    option=['pd_l1_positive','msi_h_dmmr_or_tmbh','tmb_high','her2_positive','her2_mutant','ntrk_fusion','ret_fusion','prior_checkpoint_inhibitor','cisplatin_intolerant']
    r=roles_for(p,routing=routing,option=option)
    g=Graph();S=lambda *x:list(x)
    g.decision('scope','Cervical cancer?',atom('cancer_type','eq','CERVICAL_CANCER'),'necc','outside',S('CERV-1'))
