    g.decision('common_hist','Squamous, adenocarcinoma, or adenosquamous cervical carcinoma?',atom('histology','eq','SQUAMOUS_ADENO_ADENOSQUAMOUS'),'care_met','otherhist',S('CERV-1'))
    g.status('otherhist','Histology is outside executable cervical source scope.','NEEDS_DIFFERENT_PATHWAY',S('CERV-A'))
