    g.action('necc_met','Metastatic small-cell NECC of cervix: systemic therapy preferred or best supportive care.',S('CERV-13','CERV-14'),[opt('cerv_necc_sys','Systemic therapy (cisplatin/etoposide or carboplatin/etoposide and later-line source options)','Preferred.',preference='PREFERRED'),opt('cerv_necc_bsc','Best supportive care')],support=['CERV-F'],pathway_id='CERV_NECC_METASTATIC')
    g.decision('necc_localadv','NECC locally advanced IIA-IVA / IB3?',atom('figo_stage','in',['IB3','IIA1','IIA2','IIB','IIIC1','IIIC2','III','IVA']),'necc_la','necc_early',S('CERV-13','CERV-14'))
