    g.decision('necc_la','Post-treatment NECC response assessment?',atom('treatment_phase','in',['SURVEILLANCE','LOCAL_REGIONAL_RECURRENCE','DISTANT_METASTATIC_RECURRENCE']),'necc_resp','necc_la_primary',S('CERV-14'))
    g.action('necc_la_primary','Locally advanced NECC: chemoradiation + brachytherapy +/- cisplatin/etoposide or carboplatin/etoposide preferred; neoadjuvant chemotherapy followed by chemoradiation is an alternative.',S('CERV-14'),[opt('cerv_necc_la_crt','Chemoradiation + brachytherapy +/- platinum/etoposide','Preferred.',preference='PREFERRED'),opt('cerv_necc_la_neoadj','Neoadjuvant platinum/etoposide -> chemoradiation + brachytherapy')],support=['CERV-D','CERV-F'],pathway_id='CERV_NECC_LOCALLY_ADVANCED')
