    g.action('met_later','Second/subsequent-line recurrent/metastatic cervical cancer: exact biomarker-eligible immunotherapy/targeted options plus tisotumab vedotin and cytotoxic options.',S('CERV-12'),[
      opt('cerv_later_tisotumab','Tisotumab vedotin-tftv','Category 1 preferred.',preference='PREFERRED',evidence='CATEGORY_1'),
      opt('cerv_later_pembro_pdl1','Pembrolizumab','PD-L1-positive and no inappropriate prior checkpoint reuse.',preference='PREFERRED',app=all_(atom('pd_l1_positive','eq',True),atom('prior_checkpoint_inhibitor','eq',False))),
      opt('cerv_later_pembro_msi','Pembrolizumab','MSI-H/dMMR.',preference='PREFERRED',app=all_(atom('msi_h_dmmr_or_tmbh','eq',True),atom('prior_checkpoint_inhibitor','eq',False))),
      opt('cerv_later_pembro_tmb','Pembrolizumab','TMB-H.',preference='PREFERRED',app=all_(atom('tmb_high','eq',True),atom('prior_checkpoint_inhibitor','eq',False))),
      opt('cerv_later_tdx','Fam-trastuzumab deruxtecan-nxki','HER2 IHC 3+/2+.',app=atom('her2_positive','eq',True)),
      opt('cerv_later_neratinib','Neratinib','HER2-mutant.',app=atom('her2_mutant','eq',True)),
      opt('cerv_later_ret','Selpercatinib','RET fusion.',app=atom('ret_fusion','eq',True)),
      opt('cerv_later_ntrk','Larotrectinib/entrectinib/repotrectinib','NTRK fusion.',app=atom('ntrk_fusion','eq',True)),
      opt('cerv_later_chemo','Source-listed single-agent cytotoxic therapy')],support=['CERV-F'],pathway_id='CERV_MET_LATER')
