def hodgkin_builder():
    n='nexus_hodgkin_lymphoma_v2_2026.json'; p=load(n)
    addfacts(p,[
      fact('esr_mm_hr','NUMERIC'),fact('nodal_region_count','NUMERIC'),fact('e_lesion','BOOLEAN'),fact('mediastinal_bulk','BOOLEAN'),fact('age_years','NUMERIC'),fact('anthracycline_candidate','BOOLEAN'),
      fact('prior_bv','BOOLEAN'),fact('prior_cpi','BOOLEAN'),fact('cpi_progression_lt3mo','BOOLEAN'),fact('bv_progression_lt3mo','BOOLEAN'),fact('high_risk_post_ascr','BOOLEAN'),
      fact('current_response','CODED',['CR','PR','CLINICAL_BENEFIT','NO_CLINICAL_BENEFIT','PROGRESSIVE','UNKNOWN'],semantic_unknown=['UNKNOWN']),fact('nlphl_bulky','BOOLEAN'),fact('transformation_to_aggressive_bcell','BOOLEAN')])
    # synthetic early_favorable is deterministic, not extractor authority
    routing=['cancer_type','histology','treatment_phase','stage_group','risk_system','b_symptoms','bulky_disease','age_over_60_or_unfit','pregnant','deauville','biopsy_result','transplant_candidate','relapse_timing','asymptomatic_nlphl','prior_autologous_hct','esr_mm_hr','nodal_region_count','e_lesion','mediastinal_bulk','anthracycline_candidate','current_response','nlphl_bulky','transformation_to_aggressive_bcell']
    option=['age_years','prior_bv','prior_cpi','cpi_progression_lt3mo','bv_progression_lt3mo','high_risk_post_ascr']
    r=roles_for(p,routing=routing,option=option,derived=['early_favorable'])
    # Derived early-favorable based on source risk system. False when known unfavorable criteria are met.
    ghsg_fav=all_(atom('risk_system','eq','GHSG'),atom('stage_group','in',['I','II']),atom('b_symptoms','eq',False),atom('bulky_disease','eq',False),atom('nodal_region_count','lte',2),atom('esr_mm_hr','lt',50))
