    ghsg_unfav=all_(atom('risk_system','eq','GHSG'),atom('stage_group','in',['I','II']),any_(atom('b_symptoms','eq',True),atom('bulky_disease','eq',True),atom('nodal_region_count','gte',3),all_(atom('b_symptoms','eq',False),atom('esr_mm_hr','gte',50)),all_(atom('b_symptoms','eq',True),atom('esr_mm_hr','gte',30)),atom('e_lesion','eq',True)))
    eortc_unfav=all_(atom('risk_system','eq','EORTC'),atom('stage_group','in',['I','II']),any_(atom('b_symptoms','eq',True),atom('bulky_disease','eq',True),atom('nodal_region_count','gte',4),all_(atom('b_symptoms','eq',False),atom('esr_mm_hr','gte',50)),all_(atom('b_symptoms','eq',True),atom('esr_mm_hr','gte',30))))
