    g.action('resp_fav45_action','Early favorable CHL Deauville 4-5 after 2 ABVD: continue ABVD x2 then repeat PET; Deauville 4-5 may require biopsy, with positive biopsy routing to primary refractory treatment.',S('HODG-5B'),[opt('hodg_fav45_abvd2','ABVD x2 additional cycles'),opt('hodg_fav45_repeatpet','Repeat FDG-PET/CT'),opt('hodg_fav45_biopsy','Biopsy persistent Deauville 4-5 lesion when feasible')],support=['HODG-A'],pathway_id='HODG_FAVORABLE_PET45')
    g.decision('resp_adv_unfav','Current Deauville 1-3?',atom('deauville','in',['1_2','3']),'resp_good','resp_45',S('HODG-6','HODG-7'))
    g.action('resp_good','Unfavorable/advanced CHL with favorable interim/post-treatment PET response: continue/de-escalate source-defined regimen +/- ISRT and then follow-up.',S('HODG-6','HODG-7'),[opt('hodg_resp_continue','Continue/de-escalate PET-adapted systemic therapy'),opt('hodg_resp_isrt','ISRT for source-defined bulky/residual sites',decision_relevant=False)],support=['HODG-B','HODG-C'],pathway_id='HODG_RESPONSE_GOOD')
    g.decision('resp_45','Deauville 4-5?',atom('deauville','eq','4_5'),'resp_biopsy','need_pet',S('HODG-4','HODG-6','HODG-7'))
    g.decision('resp_biopsy','Biopsy positive for CHL?',atom('biopsy_result','eq','POSITIVE'),'primary_refractory','resp_bxneg',S('HODG-4','HODG-5B','HODG-13'))
    g.action('resp_bxneg','Deauville 4-5 with negative biopsy/no refractory confirmation: continue/complete source-directed therapy or consolidation RT with short-interval reassessment rather than automatically declaring refractory disease.',S('HODG-4','HODG-5B'),[opt('hodg_bxneg_continue','Continue/complete current therapy'),opt('hodg_bxneg_rt','Consolidation ISRT','If focal PET-positive and clinically appropriate.')],support=['HODG-C'],pathway_id='HODG_PET_POS_BIOPSY_NEG')
    g.status('need_pet','Current Deauville response at the relevant treatment timepoint is required.','NEEDS_INFORMATION',S('HODG-A'))
    # RR CHL candidate / timing
    g.decision('chl_rr_candidate','Candidate for HDT/ASCR?',atom('transplant_candidate','eq',True),'rr_timing','rr_nonhct',S('HODG-13','HODG-14','HODG-15'))
    g.decision('rr_timing','Primary refractory or relapse <3 months?',atom('relapse_timing','eq','PRIMARY_REFRACTORY_OR_LT3MO'),'primary_refractory','rr_ge3',S('HODG-13','HODG-14'))
    g.action('primary_refractory','Primary refractory CHL or relapse <3 months and HDT/ASCR candidate: second-line systemic therapy, response assessment, then HDT/ASCR +/- ISRT if responsive.',S('HODG-13'),[opt('hodg_rr2_cpi','CPI-based second-line systemic therapy','Preferred where no contraindication/prior context.',app=atom('prior_cpi','eq',False)),opt('hodg_rr2_bv','BV-containing salvage','If appropriate/prior exposure allows.',app=atom('prior_bv','eq',False)),opt('hodg_rr_ascr','HDT/ASCR after response')],support=['HODG-B','HODG-C'],pathway_id='HODG_PRIMARY_REFRACTORY_ASCR')
    g.action('rr_ge3','Biopsy-proven CHL relapse >=3 months and HDT/ASCR candidate: CPI-based second-line preferred if no prior CPI; response -> HDT/ASCR +/- ISRT, with selected localized relapse RT option.',S('HODG-14'),[opt('hodg_ge3_cpi','CPI-based second-line systemic therapy','Preferred if no prior CPI exposure.',preference='PREFERRED',app=atom('prior_cpi','eq',False)),opt('hodg_ge3_salvage','Other second-line systemic therapy'),opt('hodg_ge3_ascr','HDT/ASCR after response'),opt('hodg_ge3_bvmaint','BV maintenance after HDT/ASCR','For high relapse risk and no prior BV.',app=all_(atom('high_risk_post_ascr','eq',True),atom('prior_bv','eq',False)))],support=['HODG-B','HODG-C'],pathway_id='HODG_RELAPSE_GE3_ASCR')
    g.decision('rr_nonhct','Prior CPI/BV with rapid progression?',any_(all_(atom('prior_cpi','eq',True),atom('cpi_progression_lt3mo','eq',True)),all_(atom('prior_bv','eq',True),atom('bv_progression_lt3mo','eq',True))),'rr_nonhct_later','rr_nonhct_cpi',S('HODG-15'))
    g.action('rr_nonhct_cpi','Relapsed/refractory CHL not HDT/ASCR candidate and no rapid CPI/BV failure: CPI-containing regimen x4 then continue while deriving clinical benefit +/- ISRT.',S('HODG-15'),[opt('hodg_nonhct_cpi','CPI-containing regimen','Use if no prior CPI/appropriate exposure.',app=atom('prior_cpi','eq',False)),opt('hodg_nonhct_bv','BV-containing regimen','If BV appropriate and no prior failure.',app=atom('prior_bv','eq',False)),opt('hodg_nonhct_rt','ISRT for selected sites')],support=['HODG-B','HODG-C'],pathway_id='HODG_RR_NONASCR_CPI')
    g.action('rr_nonhct_later','Relapsed/refractory CHL not HDT/ASCR candidate after rapid CPI/BV failure: subsequent non-cross-resistant systemic therapy +/- ISRT; clinical trial/center expertise strongly considered.',S('HODG-15'),[opt('hodg_nonhct_subsequent','Subsequent systemic therapy not previously used'),opt('hodg_nonhct_trial','Clinical trial'),opt('hodg_nonhct_isrt','ISRT')],support=['HODG-B','HODG-C'],pathway_id='HODG_RR_NONASCR_AFTER_FAILURE')
    g.status('outside','Outside Hodgkin lymphoma package.','OUTSIDE_ENCODED_SCOPE',S('HODG-1'))
    cons=[{'id':'hodg_stage_adv_favorable_conflict','when':all_(atom('stage_group','in',['III','IV']),atom('early_favorable','eq',True)),'message':'Stage III-IV cannot be classified as early favorable CHL.','source_pathways':['HODG-2']},
          {'id':'hodg_nlphl_chl_risk_conflict','when':all_(atom('histology','eq','NLPHL'),atom('risk_system','in',['GHSG','EORTC'])),'message':'GHSG/EORTC CHL early-risk system should not drive NLPHL routing.','source_pathways':['HODG-2','HODG-11']}]
    finalize(p,g,r,derived=derived,consistency=cons);save(n,p)
